class _AuthChangeNotifier extends ChangeNotifier {
  _AuthChangeNotifier() {
    _sub = FirebaseAuth.instance.authStateChanges().listen((_) {
      notifyListeners();
    });
  }
  late final dynamic _sub;

  /// Expuesto para que el router pueda reevaluar el redirect cuando cambia
  /// algo que no es el estado de sesiÃƒÆ’Ã‚Â³n, como el rol leÃƒÆ’Ã‚Â­do de Firestore.
  @override
  void notifyListeners() => super.notifyListeners();

  @override
  void dispose() {
    _sub.cancel();
    super.dispose();
  }
}

/// Proveedor del router ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â se crea UNA vez; el redirect se reejercuta via refreshListenable
final appRouterProvider = Provider<GoRouter>((ref) {
  final notifier = _AuthChangeNotifier();
  ref.onDispose(notifier.dispose);

  // El guard por rol depende de la lectura del perfil, que llega despuÃƒÆ’Ã‚Â©s del
  // cambio de sesiÃƒÆ’Ã‚Â³n. Sin esto el redirect se evalÃƒÆ’Ã‚Âºa una sola vez, cuando el
  // rol todavÃƒÆ’Ã‚Â­a es desconocido, y nunca se vuelve a aplicar.
  ref.listen(userRoleResolvedProvider, (_, __) => notifier.notifyListeners());
  ref.listen(currentUserRoleProvider, (_, __) => notifier.notifyListeners());
  ref.listen(
      currentUserMunicipalityProvider, (_, __) => notifier.notifyListeners());

  return GoRouter(
    initialLocation: '/splash',
    refreshListenable: notifier,
    redirect: (context, state) {
      final isLoggedIn = FirebaseAuth.instance.currentUser != null;
      final isOnSplash = state.matchedLocation == '/splash';
      // La elecciÃƒÆ’Ã‚Â³n de municipio cuelga de /auth pero es para alguien que ya
      // iniciÃƒÆ’Ã‚Â³ sesiÃƒÆ’Ã‚Â³n, asÃƒÆ’Ã‚Â­ que no entra en el rebote de las pantallas de auth:
      // si entrara, el guard de mÃƒÆ’Ã‚Â¡s abajo la devolverÃƒÆ’Ã‚Â­a acÃƒÆ’Ã‚Â¡ sin fin.
      final isOnMunicipio = state.matchedLocation.startsWith('/auth/municipio');
      final isOnAuth =
          state.matchedLocation.startsWith('/auth') && !isOnMunicipio;

      // Si estÃƒÆ’Ã‚Â¡ en splash, no redirigir (el splash decide)
      if (isOnSplash) return null;

      final target = state.matchedLocation;
      final isReport = target == '/report/new';
      // Photo capture is public. Authentication is requested only on send.
      if (!isLoggedIn && !isOnAuth && !isReport) {
        final next = isOnMunicipio ? 'report' : target;
        return '/auth/login?next=${Uri.encodeComponent(next)}';
      }
      if (isLoggedIn && isOnAuth) {
        if (ref.read(currentUserRoleProvider) == null) return null;
        return signedInDestination(state.uri.queryParameters['next']);
      }
      if (isOperationsPath(target)) {
        if (!(kIsWeb || operationsBuild)) return citizenStartLocation;
        if (ref.read(userRoleResolvedProvider) &&
            !canOpenOperations(target, ref.read(currentUserRoleProvider),
                enabled: true)) {
          return citizenStartLocation;
        }
      }
      return null;
    },
    routes: [
      // Splash
      GoRoute(
        path: '/splash',
        builder: (context, state) => const SplashScreen(),
      ),

      // Auth
      GoRoute(
        path: '/auth/welcome',
        builder: (context, state) => const WelcomeScreen(),
      ),
      GoRoute(
        path: '/auth/municipio',
        builder: (context, state) => const SelectMunicipalityScreen(),
      ),
      GoRoute(
        path: '/auth/login',
        builder: (context, state) => const LoginScreen(),
      ),
      GoRoute(
        path: '/auth/register',
        builder: (context, state) => const RegisterScreen(),
      ),
      GoRoute(
        path: '/auth/forgot-password',
        builder: (context, state) => const ForgotPasswordScreen(),
      ),

      // Ciudadano ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â mapa principal con shell de navegaciÃƒÆ’Ã‚Â³n
      ShellRoute(
        builder: (context, state, child) => _CitizenShell(child: child),
        routes: [
          GoRoute(
            path: '/map',
            builder: (context, state) => const MapScreen(),
          ),
          GoRoute(
            path: '/my-reports',
            builder: (context, state) => const MyReportsScreen(),
          ),
          GoRoute(
            path: '/notifications',
            builder: (context, state) => const NotificationsScreen(),
          ),
          GoRoute(
            path: '/profile',
            builder: (context, state) => const ProfileScreen(),
          ),
        ],
      ),

      // Consola web de gestiÃƒÆ’Ã‚Â³n y analÃƒÆ’Ã‚Â­tica. Comparte las mismas reglas y
      // streams que la app, por lo que nunca expone datos fuera del backend.
      GoRoute(
        path: '/admin',
        builder: (context, state) => const AdminConsoleScreen(),
      ),

      // Crear reporte (modal, sin shell)
      GoRoute(
        path: '/report/new',
        builder: (context, state) {
          final query = state.uri.queryParameters;
          return NewReportScreen(
            startWithCamera: query['resume'] != '1',
            initialAddressMode: query['mode'] == 'manual',
            initialLocation: _queryLocation(query['lat'], query['lng']),
          );
        },
      ),

      // Detalle de reporte (ciudadano y todos los roles)
      GoRoute(
        path: '/report/:id',
        builder: (context, state) => ReportDetailScreen(
          reportId: state.pathParameters['id']!,
        ),
      ),

      // Equipo de campo
      ShellRoute(
        builder: (context, state, child) => _FieldShell(child: child),
        routes: [
          GoRoute(
            path: '/field',
            builder: (context, state) => const FieldHomeScreen(),
          ),
          GoRoute(
            path: '/field/notifications',
            builder: (context, state) =>
                const NotificationsScreen(forFieldWorker: true),
          ),
          GoRoute(
            path: '/field/task/:id',
            builder: (context, state) => TaskDetailScreen(
              reportId: state.pathParameters['id']!,
            ),
          ),
          GoRoute(
            path: '/field/task/:id/work',
            builder: (context, state) => WorkInProgressScreen(
              reportId: state.pathParameters['id']!,
            ),
          ),
        ],
      ),

      // Coordinador
      ShellRoute(
        builder: (context, state, child) => _CoordinatorShell(child: child),
        routes: [
          GoRoute(
            path: '/coordinator',
            builder: (context, state) => const CoordinatorHomeScreen(),
          ),
          GoRoute(
            path: '/coordinator/notifications',
            builder: (context, state) => const NotificationsScreen(),
          ),
        ],
      ),
    ],
    errorBuilder: (context, state) => const Scaffold(
      body: Center(
        child: Text('No encontramos esa pÃƒÆ’Ã‚Â¡gina.'),
      ),
    ),
  );
});

LatLng? _queryLocation(String? lat, String? lng) {
  final latitude = double.tryParse(lat ?? '');
  final longitude = double.tryParse(lng ?? '');
  if (latitude == null || longitude == null) return null;
  return LatLng(latitude, longitude);
}

// ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Shells de navegaciÃƒÆ’Ã‚Â³n ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

/// Barra de navegaciÃƒÆ’Ã‚Â³n inferior para ciudadanos
class _CitizenShell extends StatelessWidget {
  final Widget child;
  const _CitizenShell({required this.child});

  @override
  Widget build(BuildContext context) {
    final location = GoRouterState.of(context).matchedLocation;
    final index = _indexFromLocation(location);

    return Scaffold(
      body: child,
      bottomNavigationBar: NavigationBar(
        selectedIndex: index,
        onDestinationSelected: (i) => _navigate(context, i),
        destinations: const [
          NavigationDestination(
            icon: Icon(Icons.map_outlined),
            selectedIcon: Icon(Icons.map),
            label: 'Mapa',
          ),
          NavigationDestination(
            icon: Icon(Icons.list_alt_outlined),
            selectedIcon: Icon(Icons.list_alt),
            label: 'Mis reportes',
          ),
          NavigationDestination(
            icon: Icon(Icons.notifications_outlined),
            selectedIcon: Icon(Icons.notifications),
            label: 'Alertas',
          ),
          NavigationDestination(
            icon: Icon(Icons.person_outline),
            selectedIcon: Icon(Icons.person),
            label: 'Perfil',
          ),
        ],
      ),
    );
  }

  int _indexFromLocation(String location) {
    if (location.startsWith('/my-reports')) return 1;
    if (location.startsWith('/notifications')) return 2;
    if (location.startsWith('/profile')) return 3;
    return 0;
  }

  void _navigate(BuildContext context, int index) {
    switch (index) {
      case 0:
        context.go('/map');
        break;
      case 1:
        context.go('/my-reports');
        break;
      case 2:
        context.go('/notifications');
        break;
      case 3:
        context.go('/profile');
        break;
    }
  }
}

/// Shell para equipo de campo (simplificado, sin NavigationBar compleja)
class _FieldShell extends StatelessWidget {
  final Widget child;
  const _FieldShell({required this.child});

  @override
  Widget build(BuildContext context) => child;
}

/// Shell para coordinador
class _CoordinatorShell extends StatelessWidget {
  final Widget child;
  const _CoordinatorShell({required this.child});

  @override
  Widget build(BuildContext context) => child;
}

