import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/theme/app_theme.dart';
import '../../../core/router/navigation_policy.dart';
import '../../../data/repositories/user_repository.dart';
import '../../../data/services/auth_service.dart';

class LoginScreen extends ConsumerStatefulWidget {
  const LoginScreen({super.key});

  @override
  ConsumerState<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends ConsumerState<LoginScreen> {
  final _formKey = GlobalKey<FormState>();
  final _emailCtrl = TextEditingController();
  final _passCtrl = TextEditingController();
  bool _loading = false;
  bool _obscure = true;

  @override
  void dispose() {
    _emailCtrl.dispose();
    _passCtrl.dispose();
    super.dispose();
  }

  void _showError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: Colors.red,
        duration: const Duration(seconds: 6),
      ),
    );
  }

  Future<void> _login() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);

    try {
      final authService = ref.read(authServiceProvider);
      final credential = await authService.loginWithEmail(
        email: _emailCtrl.text.trim(),
        password: _passCtrl.text,
      );

      // Actualizar FCM token en Firestore
      await ref
          .read(userRepositoryProvider)
          .refreshFcmToken(credential.user!.uid);

      if (mounted) _redirectByRole(credential.user!.uid);
    } on FirebaseAuthException catch (e) {
      _showError(AuthService.loginErrorMessage(e));
    } on FirebaseException catch (e) {
      // refreshFcmToken() y la lectura del perfil tocan Firestore. Si fallan,
      // sin este catch la pantalla quedaba congelada sin explicaciÃƒÆ’Ã‚Â³n.
      _showError(
        e.code == 'permission-denied'
            ? 'Entraste, pero no pudimos cargar tu perfil. '
                'Escribinos a info.consultoradiagonales@gmail.com.'
            : 'No pudimos cargar tus datos. IntentÃƒÆ’Ã‚Â¡ de nuevo.',
      );
    } catch (_) {
      _showError('No se pudo iniciar sesiÃƒÆ’Ã‚Â³n. IntentÃƒÆ’Ã‚Â¡ de nuevo.');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _loginWithGoogle() async {
    setState(() => _loading = true);
    try {
      final authService = ref.read(authServiceProvider);
      final credential = await authService.loginWithGoogle();
      await ref
          .read(userRepositoryProvider)
          .refreshFcmToken(credential.user!.uid);
      if (mounted) _redirectByRole(credential.user!.uid);
    } on FirebaseAuthException catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(AuthService.errorMessage(e))),
        );
      }
    } on FirebaseException catch (e) {
      if (mounted) {
        final message = e.code == 'permission-denied'
            ? 'Google te identificÃƒÆ’Ã‚Â³, pero no pudimos guardar tu perfil. '
                'ReintentÃƒÆ’Ã‚Â¡; si continÃƒÆ’Ã‚Âºa, escribinos a '
                'info.consultoradiagonales@gmail.com.'
            : 'Google te identificÃƒÆ’Ã‚Â³, pero no pudimos cargar tus datos. '
                'ReintentÃƒÆ’Ã‚Â¡ con conexiÃƒÆ’Ã‚Â³n a internet.';
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(message)),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
              content: Text('No se pudo iniciar sesiÃƒÆ’Ã‚Â³n con Google.')),
        );
      }
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _redirectByRole(String uid) async {
    if (!mounted) return;
    context.go(signedInDestination(
        GoRouterState.of(context).uri.queryParameters['next']));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Iniciar sesiÃƒÆ’Ã‚Â³n')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(24),
        child: Form(
          key: _formKey,
