lib/features/auth/screens/register_scree.source:
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../data/repositories/user_repository.dart';
import '../../../core/router/navigation_policy.dart';
import '../../../data/services/auth_service.dart';
import '../../../data/models/user_model.dart';
import 'package:firebase_auth/firebase_auth.dart';

class RegisterScreen extends ConsumerStatefulWidget {
  const RegisterScreen({super.key});

  @override
  ConsumerState<RegisterScreen> createState() => _RegisterScreenState();
}

class _RegisterScreenState extends ConsumerState<RegisterScreen> {
  final _formKey = GlobalKey<FormState>();
  final _nameCtrl = TextEditingController();
  final _emailCtrl = TextEditingController();
  final _passCtrl = TextEditingController();
  final _confirmCtrl = TextEditingController();
  bool _loading = false;
  bool _obscurePass = true;
  bool _obscureConfirm = true;

  @override
  void dispose() {
    _nameCtrl.dispose();
    _emailCtrl.dispose();
    _passCtrl.dispose();
    _confirmCtrl.dispose();
    super.dispose();
  }

  void _showError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: Colors.red,
        duration: const Duration(seconds: 6),
      ),
    );
  }

  Future<void> _register() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _loading = true);

    try {
      final authService = ref.read(authServiceProvider);
      final credential = await authService.registerWithEmail(
        email: _emailCtrl.text.trim(),
        password: _passCtrl.text,
      );

      // Guardar datos del usuario en Firestore
      final uid = credential.user!.uid;
      final userRepo = ref.read(userRepositoryProvider);
      await userRepo.createUser(UserModel(
        uid: uid,
        displayName: 'Usuario #${uid.substring(0, 4).toUpperCase()}',
        realName: _nameCtrl.text.trim(),
        email: _emailCtrl.text.trim(),
        role: UserRole.citizen,
        // VacÃƒÆ’Ã‚Â­o a propÃƒÆ’Ã‚Â³sito: el municipio se elige en la pantalla siguiente.
        // Poner 'default' hacÃƒÆ’Ã‚Â­a que los reportes cayeran en un municipio
        // inexistente que ningÃƒÆ’Ã‚Âºn coordinador mira.
        municipalityId: '',
        createdAt: DateTime.now(),
      ));

      await userRepo.refreshFcmToken(uid);

      if (mounted)
        context.go(signedInDestination(
            GoRouterState.of(context).uri.queryParameters['next']));
    } on FirebaseAuthException catch (e) {
      _showError(AuthService.errorMessage(e));
    } on FirebaseException catch (e) {
      // createUser() escribe en Firestore y puede fallar por reglas de
      // seguridad. Sin este catch la excepciÃƒÆ’Ã‚Â³n escapaba y la pantalla quedaba
      // congelada: la cuenta se creaba pero el usuario no veÃƒÆ’Ã‚Â­a nada.
      _showError(
        e.code == 'permission-denied'
            ? 'Tu cuenta se creÃƒÆ’Ã‚Â³ pero no pudimos guardar tu perfil. '
                'Escribinos a info.consultoradiagonales@gmail.com.'
            : 'No pudimos guardar tu perfil. IntentÃƒÆ’Ã‚Â¡ de nuevo.',
      );
    } catch (_) {
      _showError('No se pudo crear la cuenta. IntentÃƒÆ’Ã‚Â¡ de nuevo.');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Crear cuenta')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(24),
        child: Form(
          key: _formKey,
          // Sin esto los errores quedan colgados hasta el prÃƒÆ’Ã‚Â³ximo envÃƒÆ’Ã‚Â­o:
          // el usuario corrige el campo y el texto rojo sigue ahÃƒÆ’Ã‚Â­.
          autovalidateMode: AutovalidateMode.onUserInteraction,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // Nombre completo
              TextFormField(
                controller: _nameCtrl,
                decoration: const InputDecoration(
                  labelText: 'Nombre completo',
                  prefixIcon: Icon(Icons.person_outline),
                ),
                textCapitalization: TextCapitalization.words,
                validator: (v) {
                  if (v == null || v.trim().isEmpty) return 'IngresÃƒÆ’Ã‚Â¡ tu nombre';
                  if (v.trim().length < 2) return 'Nombre demasiado corto';
                  return null;
                },
              ),
              const SizedBox(height: 16),

              // Correo
              TextFormField(
                controller: _emailCtrl,
                decoration: const InputDecoration(
                  labelText: 'Correo electrÃƒÆ’Ã‚Â³nico',
                  prefixIcon: Icon(Icons.email_outlined),
                ),
                keyboardType: TextInputType.emailAddress,
                validator: (v) {
                  if (v == null || v.isEmpty) return 'IngresÃƒÆ’Ã‚Â¡ tu correo';
                  if (!v.contains('@')) return 'Correo no vÃƒÆ’Ã‚Â¡lido';
                  return null;
                },
              ),
              const SizedBox(height: 16),

              // ContraseÃƒÆ’Ã‚Â±a
              TextFormField(
                controller: _passCtrl,
                obscureText: _obscurePass,
                decoration: InputDecoration(
                  labelText: 'ContraseÃƒÆ’Ã‚Â±a',
                  prefixIcon: const Icon(Icons.lock_outline),
                  suffixIcon: IconButton(
                    icon: Icon(
                      _obscurePass ? Icons.visibility_off : Icons.visibility,
                    ),
                    onPressed: () =>
                        setState(() => _obscurePass = !_obscurePass),
                  ),
                ),
                validator: (v) {
                  if (v == null || v.isEmpty) return 'IngresÃƒÆ’Ã‚Â¡ una contraseÃƒÆ’Ã‚Â±a';
                  if (v.length < 8) return 'MÃƒÆ’Ã‚Â­nimo 8 caracteres';
                  return null;
                },
              ),
              const SizedBox(height: 16),

              // Confirmar contraseÃƒÆ’Ã‚Â±a
              TextFormField(
                controller: _confirmCtrl,
                obscureText: _obscureConfirm,
                decoration: InputDecoration(
                  labelText: 'Confirmar contraseÃƒÆ’Ã‚Â±a',
                  prefixIcon: const Icon(Icons.lock_outline),
                  suffixIcon: IconButton(
                    icon: Icon(
                      _obscureConfirm ? Icons.visibility_off : Icons.visibility,
                    ),
                    onPressed: () =>
                        setState(() => _obscureConfirm = !_obscureConfirm),
                  ),
                ),
                validator: (v) {
                  if (v != _passCtrl.text)
                    return 'Las contraseÃƒÆ’Ã‚Â±as no coinciden';
                  return null;
                },
              ),
              const SizedBox(height: 32),

              // BotÃƒÆ’Ã‚Â³n crear cuenta
              ElevatedButton(
                onPressed: _loading ? null : _register,
                child: _loading
                    ? const SizedBox(
                        height: 20,
                        width: 20,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          valueColor:
                              AlwaysStoppedAnimation<Color>(Colors.white),
                        ),
                      )
                    : const Text('Crear cuenta'),
              ),
              const SizedBox(height: 16),

              // Link a login
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  const Text('Ãƒâ€šÃ‚Â¿Ya tenÃƒÆ’Ã‚Â©s cuenta?'),
                  TextButton(
                    onPressed: () => context.go(
                        '/auth/login?next=${Uri.encodeComponent(GoRouterState.of(context).uri.queryParameters['next'] ?? 'report')}'),
                    child: const Text('IniciÃƒÆ’Ã‚Â¡ sesiÃƒÆ’Ã‚Â³n'),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

