import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/theme/app_theme.dart';
import '../../../core/utils/error_text.dart';
import '../../../core/widgets/condi_logo.dart';
import '../../../data/repositories/user_repository.dart';
import '../../../data/services/georef_service.dart';

class SelectMunicipalityScreen extends ConsumerStatefulWidget {
  const SelectMunicipalityScreen({super.key});

  @override
  ConsumerState<SelectMunicipalityScreen> createState() =>
      _SelectMunicipalityScreenState();
}

class _SelectMunicipalityScreenState
    extends ConsumerState<SelectMunicipalityScreen> {
  final _geoRef = GeoRefService();
  late final Future<List<GeoRefPlace>> _provinces = _geoRef.provinces();
  Future<List<GeoRefPlace>>? _departments;
  Future<List<GeoRefPlace>>? _municipalities;
  Future<List<GeoRefPlace>>? _localities;
  Future<List<GeoRefPlace>>? _settlements;
  GeoRefPlace? _province;
  GeoRefPlace? _department;
  GeoRefPlace? _municipality;
  GeoRefPlace? _locality;
  GeoRefPlace? _settlement;
  bool _saving = false;

  void _chooseProvince(GeoRefPlace? value) {
    if (value == null) return;
    setState(() {
      _province = value;
      _department = _municipality = _locality = _settlement = null;
      _departments = _geoRef.departments(value.id);
      _municipalities = _geoRef.municipalities(value.id);
      _localities = _geoRef.localities(value.id);
      _settlements = _geoRef.settlements(value.id);
    });
  }

  Future<void> _save() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || _province == null || _municipality == null) return;
    setState(() => _saving = true);
    try {
      await ref.read(userRepositoryProvider).updateUser(user.uid, {
        'municipalityId': 'georef_${_municipality!.id}',
        'municipalityName': _municipality!.name,
        'provinceId': _province!.id,
        'province': _province!.name,
        'departmentId': _department?.id,
        'department': _department?.name,
        'localityId': _locality?.id,
        'locality': _locality?.name,
        'settlementId': _settlement?.id,
        'settlement': _settlement?.name,
      });
      if (mounted)
        context.go(
            GoRouterState.of(context).uri.queryParameters['next'] == 'report'
                ? '/report/new?resume=1'
                : '/report/new?mode=camera');
    } catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text(mensajeDeError(error)), backgroundColor: Colors.red));
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
        appBar: AppBar(title: const Text('Tu ubicaciÃƒÆ’Ã‚Â³n')),
        body: SafeArea(
          child: FutureBuilder<List<GeoRefPlace>>(
            future: _provinces,
            builder: (context, snapshot) {
              if (snapshot.connectionState != ConnectionState.done) {
                return const Center(child: CircularProgressIndicator());
              }
              if (snapshot.hasError)
                return Center(child: Text(mensajeDeError(snapshot.error!)));
              return ListView(padding: const EdgeInsets.all(24), children: [
                const Center(child: CondiLogo(fontSize: 34)),
                const SizedBox(height: 24),
                Text('Ãƒâ€šÃ‚Â¿DÃƒÆ’Ã‚Â³nde vivÃƒÆ’Ã‚Â­s?',
                    style: Theme.of(context).textTheme.titleLarge,
                    textAlign: TextAlign.center),
                const SizedBox(height: 8),
                Text(
                    'ElegÃƒÆ’Ã‚Â­ tu provincia y municipio o partido. PodÃƒÆ’Ã‚Â©s completar localidad y paraje para mejorar cada reporte.',
                    textAlign: TextAlign.center,
                    style: Theme.of(context)
                        .textTheme
                        .bodyMedium
                        ?.copyWith(color: AppColors.textSecondary)),
                const SizedBox(height: 24),
                _dropdown(
                    'Provincia *', snapshot.data!, _province, _chooseProvince),
                if (_province != null) ...[
                  _asyncDropdown('Municipio o partido *', _municipalities,
                      _municipality, (v) => setState(() => _municipality = v)),
                  _asyncDropdown('Departamento', _departments, _department,
                      (v) => setState(() => _department = v)),
                  _asyncDropdown('Ciudad o localidad', _localities, _locality,
                      (v) => setState(() => _locality = v)),
                  _asyncDropdown('Paraje o asentamiento', _settlements,
                      _settlement, (v) => setState(() => _settlement = v)),
                ],
                const SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      _province == null || _municipality == null || _saving
                          ? null
                          : _save,
                  child: _saving
                      ? const SizedBox(
                          height: 20,
                          width: 20,
                          child: CircularProgressIndicator(strokeWidth: 2))
                      : const Text('Continuar'),
                ),
              ]);
            },
          ),
        ),
      );

  Widget _asyncDropdown(String label, Future<List<GeoRefPlace>>? future,
      GeoRefPlace? selected, ValueChanged<GeoRefPlace?> onChanged) {
    if (future == null) return const SizedBox.shrink();
    return FutureBuilder<List<GeoRefPlace>>(
      future: future,
      builder: (context, snapshot) => !snapshot.hasData
          ? const Padding(
              padding: EdgeInsets.symmetric(vertical: 12),
              child: LinearProgressIndicator())
          : _dropdown(label, snapshot.data!, selected, onChanged),
    );
  }

  Widget _dropdown(String label, List<GeoRefPlace> options,
          GeoRefPlace? selected, ValueChanged<GeoRefPlace?> onChanged) =>
      Padding(
        padding: const EdgeInsets.only(bottom: 16),
        child: DropdownButtonFormField<GeoRefPlace>(
          value: selected,
          isExpanded: true,
          decoration: InputDecoration(labelText: label),
          hint: Text('SeleccionÃƒÆ’Ã‚Â¡ $label'),
          items: options
              .map((place) => DropdownMenuItem(
                  value: place,
                  child: Text(place.name, overflow: TextOverflow.ellipsis)))
              .toList(),
          onChanged: onChanged,
        ),
      );
}

lib/features/profile/screens/profile_scr.source:
import 'package:flutter/material.dart';
import 'package:flutter/foundation.dart' show kIsWeb;
import '../../../core/router/navigation_policy.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/theme/app_theme.dart';
import '../../../data/repositories/user_repository.dart';
import '../../../data/services/auth_service.dart';
import '../../../core/utils/error_text.dart';

class ProfileScreen extends ConsumerWidget {
  const ProfileScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final user = ref.watch(authStateProvider).valueOrNull;
    if (user == null) return const SizedBox.shrink();

    final userAsync = ref.watch(currentUserProfileProvider(user.uid));

    return Scaffold(
      appBar: AppBar(title: const Text('Mi perfil')),
      body: userAsync.when(
        loading: () => const Center(child: CircularProgressIndicator()),
        error: (e, _) => Center(child: Text(mensajeDeError(e))),
        data: (userModel) => ListView(
          padding: const EdgeInsets.all(24),
          children: [
            // Avatar
            Center(
              child: CircleAvatar(
                radius: 48,
                backgroundColor: AppColors.primary.withOpacity(0.15),
                child: Text(
                  userModel?.realName.isNotEmpty == true
                      ? userModel!.realName[0].toUpperCase()
                      : '?',
                  style:
                      const TextStyle(fontSize: 36, color: AppColors.primary),
                ),
              ),
            ),
            const SizedBox(height: 16),
            Center(
              child: Text(
                userModel?.realName ?? '',
                style:
                    const TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
              ),
            ),
            Center(
              child: Text(
                userModel?.email ?? '',
                style: const TextStyle(color: AppColors.textSecondary),
              ),
            ),
            const SizedBox(height: 8),
            Center(
              child: Chip(
                label: Text(
                  _rolLabel(userModel?.role.value ?? 'citizen'),
                  style: const TextStyle(fontSize: 12),
                ),
                backgroundColor: AppColors.primary.withOpacity(0.1),
              ),
            ),
            const SizedBox(height: 32),

            // Stats
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                _StatTile(
                    label: 'Reportes',
                    value: '${userModel?.reportsCount ?? 0}'),
              ],
            ),
            const Divider(height: 40),

            // Opciones
            _MenuItem(
              icon: Icons.lock_outline,
              label: 'Cambiar contraseÃƒÆ’Ã‚Â±a',
              onTap: () => _changePassword(context, ref),
            ),
            if ((kIsWeb || operationsBuild) &&
                user.email?.toLowerCase() ==
                    'info.consultoradiagonales@gmail.com' &&
                userModel?.role.value != 'admin')
              _MenuItem(
                icon: Icons.admin_panel_settings_outlined,
                label: 'Activar administraciÃƒÆ’Ã‚Â³n ConDi',
                color: AppColors.brandBlue,
                onTap: () => _activateAdmin(context, ref),
              ),
            if ((kIsWeb || operationsBuild) && userModel?.role.value == 'admin')
              _MenuItem(
                icon: Icons.dashboard_outlined,
                label: 'Abrir panel de gestiÃƒÆ’Ã‚Â³n',
                color: AppColors.brandBlue,
                onTap: () => context.go('/admin'),
              ),
            _MenuItem(
              icon: Icons.privacy_tip_outlined,
              label: 'PolÃƒÆ’Ã‚Â­tica de privacidad',
              onTap: () {/* TODO: abrir URL */},
            ),
            _MenuItem(
              icon: Icons.info_outline,
              label: 'Acerca de la app',
              onTap: () {/* TODO: pantalla about */},
            ),
            const Divider(height: 32),

            // Cerrar sesiÃƒÆ’Ã‚Â³n
            _MenuItem(
              icon: Icons.logout,
              label: 'Cerrar sesiÃƒÆ’Ã‚Â³n',
              color: Colors.orange,
              onTap: () async {
                await ref.read(authServiceProvider).signOut();
                if (context.mounted) context.go('/report/new?mode=camera');
              },
            ),

            // Eliminar cuenta (Play Store obligatorio)
            _MenuItem(
              icon: Icons.delete_forever_outlined,
              label: 'Eliminar mi cuenta',
              color: Colors.red,
              onTap: () => _confirmDeleteAccount(context, ref, user.uid),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _confirmDeleteAccount(
      BuildContext context, WidgetRef ref, String uid) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Eliminar cuenta'),
        content: const Text(
          'Esta acciÃƒÆ’Ã‚Â³n es irreversible. Se eliminarÃƒÆ’Ã‚Â¡n tu cuenta y todos tus datos. '
          'Tus reportes quedarÃƒÆ’Ã‚Â¡n anÃƒÆ’Ã‚Â³nimos en el mapa.\n\n'
          'Ãƒâ€šÃ‚Â¿EstÃƒÆ’Ã‚Â¡s seguro/a?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancelar'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            onPressed: () => Navigator.pop(context, true),
            child:
                const Text('Eliminar', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );

    if (confirmed != true || !context.mounted) return;

    try {
      await ref.read(userRepositoryProvider).deleteUserData(uid);
      await ref.read(authServiceProvider).deleteAccount();
      if (context.mounted) context.go('/report/new?mode=camera');
    } catch (e) {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Para eliminar tu cuenta, cerrÃƒÆ’Ã‚Â¡ sesiÃƒÆ’Ã‚Â³n y volvÃƒÆ’Ã‚Â© a iniciarla primero.',
            ),
          ),
        );
      }
    }
  }

  Future<void> _activateAdmin(BuildContext context, WidgetRef ref) async {
    try {
      await ref.read(authServiceProvider).activateOwnerAdmin();
      if (context.mounted) context.go('/admin');
    } catch (error) {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(mensajeDeError(error))),
        );
      }
    }
  }

  Future<void> _changePassword(BuildContext context, WidgetRef ref) async {
    final current = TextEditingController();
    final next = TextEditingController();
    final confirm = TextEditingController();
    final result = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Cambiar contraseÃƒÆ’Ã‚Â±a'),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(
              controller: current,
              obscureText: true,
              decoration:
                  const InputDecoration(labelText: 'ContraseÃƒÆ’Ã‚Â±a actual')),
          const SizedBox(height: 10),
          TextField(
              controller: next,
              obscureText: true,
              decoration: const InputDecoration(
                  labelText: 'Nueva contraseÃƒÆ’Ã‚Â±a (8 caracteres mÃƒÆ’Ã‚Â­nimo)')),
          const SizedBox(height: 10),
          TextField(
              controller: confirm,
              obscureText: true,
              decoration:
                  const InputDecoration(labelText: 'Repetir nueva contraseÃƒÆ’Ã‚Â±a')),
        ]),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Cancelar')),
          ElevatedButton(
            onPressed: () {
              if (next.text.length < 8 || next.text != confirm.text) return;
              Navigator.pop(dialogContext, true);
            },
            child: const Text('Guardar'),
          ),
        ],
      ),
    );
    if (result != true || !context.mounted) return;
    try {
      await ref.read(authServiceProvider).changePassword(
            currentPassword: current.text,
            newPassword: next.text,
          );
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('ContraseÃƒÆ’Ã‚Â±a actualizada.')),
        );
      }
    } catch (error) {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(mensajeDeError(error))),
        );
      }
    } finally {
      current.dispose();
      next.dispose();
      confirm.dispose();
    }
  }

  String _rolLabel(String role) {
    switch (role) {
      case 'field_worker':
        return 'Equipo de campo';
      case 'coordinator':
        return 'Coordinador';
      case 'admin':
        return 'Administrador';
      case 'moderator':
        return 'Moderador';
      default:
        return 'Ciudadano';
    }
  }
}

class _StatTile extends StatelessWidget {
  final String label;
  final String value;
  const _StatTile({required this.label, required this.value});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Text(value,
            style: const TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
                color: AppColors.primary)),
        Text(label,
            style:
                const TextStyle(fontSize: 12, color: AppColors.textSecondary)),
      ],
    );
  }
}

class _MenuItem extends StatelessWidget {
  final IconData icon;
  final String label;
  final VoidCallback onTap;
  final Color? color;
  const _MenuItem(
      {required this.icon,
      required this.label,
      required this.onTap,
      this.color});

  @override
  Widget build(BuildContext context) {
    final c = color ?? AppColors.onSurface;
    return ListTile(
