import 'package:firebase_core/firebase_core.dart';

/// Traduce cualquier excepciÃƒÆ’Ã‚Â³n a un mensaje que se le pueda mostrar a un
/// vecino. Nunca devuelve cÃƒÆ’Ã‚Â³digos, nombres de servicios ni stack traces: un
/// "[cloud_firestore/permission-denied] Missing or insufficient permissions"
/// en pantalla no le sirve a nadie y expone el funcionamiento interno.
String mensajeDeError(Object error) {
  if (error is StateError) return error.message.toString();
  final texto = error is FirebaseException
      ? '${error.plugin}/${error.code} ${error.message ?? ''}'.toLowerCase()
      : error.toString().toLowerCase();

  bool tiene(String aguja) => texto.contains(aguja);

  if (tiene('permission-denied') || tiene('unauthenticated')) {
    return 'No tenÃƒÆ’Ã‚Â©s permiso para ver esto. '
        'Si creÃƒÆ’Ã‚Â©s que es un error, escribinos a info.consultoradiagonales@gmail.com.';
  }
  if (tiene('unavailable') ||
      tiene('network') ||
      tiene('socket') ||
      tiene('timeout') ||
      tiene('deadline-exceeded')) {
    return 'Sin conexiÃƒÆ’Ã‚Â³n. RevisÃƒÆ’Ã‚Â¡ tu internet e intentÃƒÆ’Ã‚Â¡ de nuevo.';
  }
  if (tiene('not-found')) {
    return 'No encontramos lo que buscabas.';
  }
  if (tiene('resource-exhausted') || tiene('quota')) {
    return 'El servicio estÃƒÆ’Ã‚Â¡ saturado. ProbÃƒÆ’Ã‚Â¡ en unos minutos.';
  }
  if (tiene('cancelled')) {
    return 'La operaciÃƒÆ’Ã‚Â³n se cancelÃƒÆ’Ã‚Â³.';
  }
  if (tiene('unauthorized') || tiene('storage/')) {
    return 'No pudimos subir la imagen. IntentÃƒÆ’Ã‚Â¡ de nuevo.';
  }
  return 'Algo saliÃƒÆ’Ã‚Â³ mal. IntentÃƒÆ’Ã‚Â¡ de nuevo en unos minutos.';
}

