import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/services/report_permissions.dart';
import '../../../core/utils/error_text.dart';
import '../report_flow.dart';
import '../report_insight.dart';

/// Photo -> confirmed location -> optional detail -> server confirmation.
class NewReportScreen extends ConsumerStatefulWidget {
  const NewReportScreen(
      {super.key,
      this.startWithCamera = true,
      this.initialAddressMode = false,
      this.initialLocation,
      this.showMap = true});
  final bool startWithCamera;
  final bool initialAddressMode;
  final LatLng? initialLocation;
  final bool showMap;
  @override
  ConsumerState<NewReportScreen> createState() => _NewReportScreenState();
}

class _NewReportScreenState extends ConsumerState<NewReportScreen> {
  final _comment = TextEditingController();
  final _address = TextEditingController();
  int _step = 0;
  bool _openingCamera = false, _locating = false, _sending = false;
  String? _error, _sentId;
  bool _sentWithAi = false;
  Future<Uint8List>? _preview;
  GoogleMapController? _map;
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _start());
  }

  @override
  void dispose() {
    _comment.dispose();
    _address.dispose();
    _map?.dispose();
    super.dispose();
  }

  ReportDraft get _draft => ref.read(reportDraftProvider);
  void _update(ReportDraft draft) =>
      ref.read(reportDraftProvider.notifier).update(draft);
  Future<void> _start() async {
    await ref.read(reportDraftProvider.notifier).ready;
    if (!mounted) return;
    try {
      final recovered = await ref.read(reportCaptureProvider).recoverPhoto();
      if (recovered != null)
        _update(
            _draft.copyWith(photoPath: recovered.path, clearLocation: true));
      if (_draft.hasPhoto) {
        try {
          final bytes = await ref
              .read(reportCaptureProvider)
              .readPhoto(_draft.photoPath!);
          _preview = Future.value(bytes);
        } catch (_) {
          await ref.read(reportDraftProvider.notifier).clear();
        }
      }
      if (!mounted) return;
      _comment.text = _draft.comment;
      _address.text = _draft.address;
      if (widget.initialLocation != null && !_draft.locationConfirmed) {
        _update(_draft.copyWith(location: widget.initialLocation));
      }
      if (_draft.hasPhoto) {
        setState(() => _step = _draft.locationConfirmed ? 2 : 1);
        if (_draft.location == null) await _gps();
      } else if (widget.startWithCamera) {
        await _camera();
      }
    } catch (e) {
      if (mounted) setState(() => _error = mensajeDeError(e));
    }
  }

  Future<void> _camera() async {
    if (_openingCamera || _sending) return;
    setState(() {
      _openingCamera = true;
      _error = null;
    });
    try {
      final photo = await ref.read(reportCaptureProvider).camera();
      if (photo == null || !mounted) return;
      final bytes = await ref.read(reportCaptureProvider).readPhoto(photo.path);
      if (!mounted) return;
      _update(_draft.copyWith(photoPath: photo.path, clearLocation: true));
      _preview = Future.value(bytes);
      setState(() => _step = 1);
      await _gps();
    } catch (e) {
      if (mounted) setState(() => _error = mensajeDeError(e));
    } finally {
      if (mounted) setState(() => _openingCamera = false);
    }
  }

  Future<void> _gps() async {
    if (_locating) return;
    setState(() {
      _locating = true;
      _error = null;
    });
    try {
      final location = await ref.read(reportCaptureProvider).gps();
      if (!mounted) return;
      _update(_draft.copyWith(location: location, locationConfirmed: false));
      await _map?.animateCamera(CameraUpdate.newLatLng(location));
    } catch (e) {
      if (mounted) setState(() => _error = mensajeDeError(e));
    } finally {
      if (mounted) setState(() => _locating = false);
    }
  }

  void _markLocation(LatLng point) {
    _update(_draft.copyWith(location: point, locationConfirmed: false));
    setState(() => _error = null);
  }

  Future<bool> _identify() async {
    final service = ref.read(reportSubmitProvider);
    if (service.signedIn) return true;
    final choice = await showModalBottomSheet<String>(
        context: context,
        showDragHandle: true,
        builder: (context) => SafeArea(
            child: Padding(
                padding: const EdgeInsets.all(24),
                child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Text('Identificate para enviar',
                          style: Theme.of(context).textTheme.titleLarge),
                      const SizedBox(height: 8),
                      const Text(
                          'La foto y la ubicaciÃƒÆ’Ã‚Â³n quedan guardadas mientras iniciÃƒÆ’Ã‚Â¡s sesiÃƒÆ’Ã‚Â³n.'),
                      const SizedBox(height: 20),
                      FilledButton.icon(
                          onPressed: () => Navigator.pop(context, 'google'),
                          icon: const Icon(Icons.g_mobiledata, size: 28),
                          label: const Text('Continuar con Google')),
                      TextButton(
                          onPressed: () => Navigator.pop(context, 'email'),
                          child: const Text('Usar correo y contraseÃƒÆ’Ã‚Â±a')),
                    ]))));
    if (!mounted) return false;
    if (choice == 'google') {
      await service.loginWithGoogle();
      return service.signedIn;
    }
    if (choice == 'email') context.go('/auth/login?next=report');
    return false;
  }

  Future<void> _send() async {
    if (_sending || !_draft.canSend) return;
    setState(() {
      _sending = true;
      _error = null;
    });
    try {
      if (!await _identify() || !mounted) return;
      final wantsAi = _draft.aiRequested;
      final id = await ref.read(reportSubmitProvider).submit(_draft);
      await ref.read(reportDraftProvider.notifier).clear();
      if (mounted) setState(() { _sentId = id; _sentWithAi = wantsAi; });
    } on MunicipalityRequired {
      if (mounted) context.go('/auth/municipio?next=report');
    } catch (e) {
      if (mounted) setState(() => _error = mensajeDeError(e));
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _newPhoto() async {
    await ref.read(reportDraftProvider.notifier).clear();
    _comment.clear();
    _address.clear();
    setState(() {
      _sentId = null;
      _step = 0;
      _preview = null;
      _error = null;
    });
    await _camera();
  }

  @override
  Widget build(BuildContext context) {
    final draft = ref.watch(reportDraftProvider);
    final colors = Theme.of(context).colorScheme;
    return Scaffold(
      appBar: AppBar(
          title: const Text('ConDi'),
          automaticallyImplyLeading: false,
          actions: [
            PopupMenuButton<String>(
                tooltip: 'Mis reportes y mapa',
                onSelected: (path) => context.go(path),
                itemBuilder: (_) => const [
                      PopupMenuItem(
                          value: '/my-reports', child: Text('Mis reportes')),
                      PopupMenuItem(
                          value: '/map', child: Text('Mapa del barrio')),
                      PopupMenuItem(
                          value: '/profile', child: Text('Mi cuenta')),
                    ])
          ]),
      body: SafeArea(
          child: Center(
              child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 640),
                  child: _sentId != null
                      ? _success(context)
                      : Column(children: [
                          Padding(
                              padding: const EdgeInsets.fromLTRB(20, 8, 20, 12),
                              child: Row(
                                  children: List.generate(
                                      3,
                                      (i) => Expanded(
                                          child: Padding(
                                              padding:
                                                  const EdgeInsets.symmetric(
                                                      horizontal: 3),
                                              child: Column(children: [
                                                LinearProgressIndicator(
                                                    value: i <= _step ? 1 : 0,
                                                    minHeight: 5,
                                                    borderRadius:
                                                        BorderRadius.circular(
                                                            5)),
                                                const SizedBox(height: 6),
                                                Text(
                                                    [
                                                      '1 Ãƒâ€šÃ‚Â· Foto',
                                                      '2 Ãƒâ€šÃ‚Â· UbicaciÃƒÆ’Ã‚Â³n',
                                                      '3 Ãƒâ€šÃ‚Â· Enviar'
                                                    ][i],
                                                    style: TextStyle(
                                                        fontSize: 12,
                                                        color: i <= _step
                                                            ? colors.primary
                                                            : colors
                                                                .onSurfaceVariant))
                                              ])))))),
                          Expanded(
                              child: ListView(
                                  padding:
                                      const EdgeInsets.fromLTRB(20, 8, 20, 24),
                                  children: [
                                Text(
                                    [
                                      'MostrÃƒÆ’Ã‚Â¡ el problema',
                                      'Ãƒâ€šÃ‚Â¿DÃƒÆ’Ã‚Â³nde estÃƒÆ’Ã‚Â¡?',
                                      'Listo para enviar'
                                    ][_step],
                                    style: Theme.of(context)
                                        .textTheme
                                        .headlineSmall
                                        ?.copyWith(
                                            fontWeight: FontWeight.bold)),
                                const SizedBox(height: 8),
                                Text([
                                  'SacÃƒÆ’Ã‚Â¡ una foto para empezar.',
                                  'ConfirmÃƒÆ’Ã‚Â¡ el punto o ajustalo tocando el mapa.',
                                  'ElegÃƒÆ’Ã‚Â­ una opciÃƒÆ’Ã‚Â³n o enviÃƒÆ’Ã‚Â¡ solo la foto y la ubicaciÃƒÆ’Ã‚Â³n.'
                                ][_step]),
                                const SizedBox(height: 18),
                                if (_step == 0) _photoStart(context),
                                if (_step == 1)
                                  ..._locationStep(context, draft),
                                if (_step == 2) ..._detailsStep(context, draft),
                                if (_error != null)
                                  Padding(
                                      padding: const EdgeInsets.only(top: 16),
                                      child: Column(
                                          crossAxisAlignment:
                                              CrossAxisAlignment.start,
                                          children: [
                                            Text(_error!,
                                                style: TextStyle(
                                                    color: colors.error)),
                                            if (_step < 2)
                                              TextButton(
                                                  onPressed: ReportPermissions
                                                      .openSettings,
                                                  child: const Text(
                                                      'Revisar permisos'))
                                          ])),
                              ])),
                          Padding(
                              padding: const EdgeInsets.fromLTRB(20, 8, 20, 16),
                              child: Row(children: [
                                if (_step > 0)
                                  IconButton(
                                      tooltip: 'AtrÃƒÆ’Ã‚Â¡s',
                                      icon: const Icon(Icons.arrow_back),
                                      onPressed: _sending
                                          ? null
                                          : () => setState(() => _step--)),
                                if (_step == 1)
                                  Expanded(
                                      child: FilledButton(
                                          onPressed: draft.location == null ||
                                                  _locating
                                              ? null
                                              : () {
                                                  _update(draft.copyWith(
                                                      locationConfirmed: true));
                                                  setState(() {
                                                    _step = 2;
                                                    _error = null;
                                                  });
                                                },
                                          child: const Text(
                                              'Usar esta ubicaciÃƒÆ’Ã‚Â³n',
                                              textAlign: TextAlign.center))),
                                if (_step == 2)
                                  Expanded(
                                      child: FilledButton.icon(
                                          onPressed: _sending ? null : _send,
                                          icon: _sending
                                              ? const SizedBox(
                                                  width: 18,
                                                  height: 18,
                                                  child:
                                                      CircularProgressIndicator(
                                                          strokeWidth: 2))
                                              : const Icon(Icons.send_outlined),
                                          label: Text(_sending
                                              ? 'EnviandoÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦'
                                              : 'Enviar reporte'))),
                              ])),
                        ])))),
    );
  }

  Widget _photoStart(BuildContext context) => Container(
      padding: const EdgeInsets.symmetric(vertical: 50, horizontal: 24),
      decoration: BoxDecoration(
          color: Theme.of(context).colorScheme.surfaceContainerHighest,
          borderRadius: BorderRadius.circular(24)),
      child: Column(children: [
        const Icon(Icons.add_a_photo_outlined, size: 72),
        const SizedBox(height: 24),
        FilledButton.icon(
            key: const Key('take-photo'),
            onPressed: _openingCamera ? null : _camera,
            icon: const Icon(Icons.camera_alt_outlined),
            label: Text(_openingCamera ? 'Abriendo cÃƒÆ’Ã‚Â¡maraÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦' : 'Sacar foto'))
      ]));
  Widget _photo({double height = 170}) => ClipRRect(
      borderRadius: BorderRadius.circular(18),
      child: SizedBox(
          height: height,
          width: double.infinity,
          child: FutureBuilder<Uint8List>(
              future: _preview,
              builder: (context, snapshot) => snapshot.hasData
                  ? Image.memory(snapshot.data!,
                      fit: BoxFit.cover,
                      errorBuilder: (_, __, ___) => const Center(
                          child: Text('Vista previa no disponible')))
                  : const Center(child: CircularProgressIndicator()))));
  List<Widget> _locationStep(BuildContext context, ReportDraft draft) => [
        _photo(height: 130),
        const SizedBox(height: 12),
        SizedBox(
            height: 260,
            child: ClipRRect(
                borderRadius: BorderRadius.circular(18),
                child: widget.showMap
                    ? GoogleMap(
                        initialCameraPosition: CameraPosition(
                            target: draft.location ??
                                const LatLng(-34.92145, -57.95453),
                            zoom: 16),
                        onMapCreated: (controller) => _map = controller,
                        onTap: _markLocation,
                        myLocationButtonEnabled: false,
                        zoomControlsEnabled: true,
                        markers: draft.location == null
                            ? {}
                            : {
                                Marker(
                                    markerId: const MarkerId('issue'),
                                    position: draft.location!,
                                    draggable: true,
                                    onDragEnd: _markLocation)
                              })
                    : const Center(
                        child: Icon(Icons.location_on_outlined, size: 64)))),
        const SizedBox(height: 8),
        if (draft.location != null)
          Text(
              '${draft.location!.latitude.toStringAsFixed(5)}, ${draft.location!.longitude.toStringAsFixed(5)}'),
        TextButton.icon(
            onPressed: _locating ? null : _gps,
            icon: const Icon(Icons.my_location),
            label:
                Text(_locating ? 'Buscando ubicaciÃƒÆ’Ã‚Â³nÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦' : 'Usar mi ubicaciÃƒÆ’Ã‚Â³n')),
        TextField(
            controller: _address,
            maxLength: 180,
            onChanged: (value) => _update(_draft.copyWith(address: value)),
            decoration: const InputDecoration(
                labelText: 'Referencia de la direcciÃƒÆ’Ã‚Â³n (opcional)',
                hintText: 'Ej.: frente al 1236')),
      ];
  List<Widget> _detailsStep(BuildContext context, ReportDraft draft) => [
        _photo(),
        const SizedBox(height: 12),
        Row(children: [
          const Icon(Icons.location_on_outlined, size: 20),
          const SizedBox(width: 6),
