class ReportDetailScreen extends ConsumerStatefulWidget {
  final String reportId;
  const ReportDetailScreen({super.key, required this.reportId});

  @override
  ConsumerState<ReportDetailScreen> createState() =>
      _ReportDetailScreenState();
}

class _ReportDetailScreenState extends ConsumerState<ReportDetailScreen> {
  bool _voting = false;
  bool _flagging = false;
  late final Future<ReportModel?> _reportFuture;

  @override
  void initState() {
    super.initState();
    // No crear el provider dentro de build: cada reconstrucciÃƒÆ’Ã‚Â³n reiniciaba la
    // lectura de Firestore y la pantalla podÃƒÆ’Ã‚Â­a quedar en el spinner.
    _reportFuture = ref.read(reportsRepositoryProvider).getReport(widget.reportId);
  }

  Future<void> _toggleSupport(ReportModel report) async {
    final uid = ref.read(authStateProvider).valueOrNull?.uid;
    if (uid == null) return;

    setState(() => _voting = true);
    try {
      await ref
          .read(reportsRepositoryProvider)
          .addSupportVote(report.id, uid);
    } finally {
      if (mounted) setState(() => _voting = false);
    }
  }

  Future<void> _flagReport(ReportModel report) async {
    final uid = ref.read(authStateProvider).valueOrNull?.uid;
    if (uid == null) return;

    final reason = await showDialog<String>(
      context: context,
      builder: (_) => _FlagDialog(),
    );
    if (reason == null || !mounted) return;

    setState(() => _flagging = true);
    try {
      await ref
          .read(reportsRepositoryProvider)
          .flagContent(
            reportedBy: uid,
            targetType: 'report',
            targetId: report.id,
            reportId: report.id,
            reason: reason,
          );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Reporte enviado al moderador.')),
        );
      }
    } finally {
      if (mounted) setState(() => _flagging = false);
    }
  }

  Future<void> _rateReport(ReportModel report) async {
    final uid = ref.read(authStateProvider).valueOrNull?.uid;
    if (uid == null) return;
    if (report.status != ReportStatus.resolved &&
        report.status != ReportStatus.closed) return;

    int? rating;
    await showModalBottomSheet(
      context: context,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (_) => _RatingSheet(
        onRate: (r) {
          rating = r;
          Navigator.pop(context);
        },
      ),
    );

    if (rating == null) return;
    await ref.read(reportsRepositoryProvider).updateReport(report.id, {
      'rating': rating,
    });
  }

  @override
  Widget build(BuildContext context) {
    final uid = ref.watch(authStateProvider).valueOrNull?.uid ?? '';
    final role = ref.watch(currentUserRoleProvider);
    final isStaff = role == 'admin' ||
        role == 'coordinator' ||
        role == 'moderator';

    return Scaffold(
      appBar: AppBar(
        title: const Text('Detalle del reporte'),
        actions: [
          if (isStaff)
            PopupMenuButton<String>(
              tooltip: 'NavegaciÃƒÆ’Ã‚Â³n de gestiÃƒÆ’Ã‚Â³n',
              icon: const Icon(Icons.menu),
              onSelected: (route) => context.go(route),
              itemBuilder: (_) => [
                const PopupMenuItem(
                  value: '/admin',
                  child: ListTile(
                    leading: Icon(Icons.dashboard_outlined),
                    title: Text('Centro de gestiÃƒÆ’Ã‚Â³n'),
                    contentPadding: EdgeInsets.zero,
                  ),
                ),
                const PopupMenuItem(
                  value: '/coordinator',
