function fakeDb(seed = {}) {
  const docs = new Map(Object.entries(seed));
  return { docs, collection:c=>({doc:id=>({key:c+'/'+id})}), runTransaction:async fn=>fn({
    get:async ref=>({data:()=>docs.get(ref.key)}),
    set:(ref,value,options)=>docs.set(ref.key, options?.merge ? {...docs.get(ref.key),...value}:value),
  }) };
}
test('Reservation blocks duplicate delivery, terminal states and daily quota', async () => {
  const now=new Date('2026-10-12T12:00:00Z');
  const db=fakeDb();
  assert.equal(await reserve(db,'r','u',now), true);
  db.docs.get('reportInsights/r').startedAt={toMillis:()=>now.getTime()};
  assert.equal(await reserve(db,'r','u',now), false);
  assert.equal(db.docs.get('_aiUsage/2026-10-12').count,1);
  const limited=fakeDb({'_aiUsage/2026-10-12_u':{count:10}});
  assert.equal(await reserve(limited,'r','u',now), false);
  assert.equal(limited.docs.get('reportInsights/r').reason,'usage_limit');
  const done=fakeDb({'reportInsights/r':{status:'ready'}});
  assert.equal(await reserve(done,'r','u',now),false);
});

const { onCall, HttpsError } = require('firebase-functions/v2/https');
const { initializeApp } = require('firebase-admin/app');
// FieldValue se importa del submÃƒÆ’Ã‚Â³dulo: en firebase-admin v12
// admin.firestore.FieldValue quedÃƒÆ’Ã‚Â³ undefined.
const { getFirestore, FieldValue } = require('firebase-admin/firestore');

initializeApp();
const db = getFirestore();
exports.interpretCitizenReport = require('./ai-trigger').interpretCitizenReport;

const ROLES_GESTION = ['coordinator', 'admin', 'moderator'];
const ESTADOS_ASIGNABLES = ['pending', 'assigned'];
const OWNER_EMAIL = 'info.consultoradiagonales@gmail.com';

/**
 * Alta ÃƒÆ’Ã‚Âºnica del propietario de ConDi. El correo estÃƒÆ’Ã‚Â¡ fijado al titular del
 * proyecto: ningÃƒÆ’Ã‚Âºn usuario registrado puede convertirse en administrador.
 */
exports.activateOwnerAdmin = onCall(async (request) => {
  const uid = request.auth?.uid;
  const email = request.auth?.token?.email?.toLowerCase();
  if (!uid) {
    throw new HttpsError('unauthenticated', 'TenÃƒÆ’Ã‚Â©s que iniciar sesiÃƒÆ’Ã‚Â³n.');
  }
  if (email !== OWNER_EMAIL) {
    throw new HttpsError('permission-denied', 'Solo el titular puede activar la administraciÃƒÆ’Ã‚Â³n.');
  }

  const owner = await db.collection('users').doc(uid).get();
  if (!owner.exists) {
    throw new HttpsError('failed-precondition', 'CompletÃƒÆ’Ã‚Â¡ primero el registro de tu cuenta.');
  }
  await owner.ref.update({
    role: 'admin',
    disabled: false,
    updatedAt: FieldValue.serverTimestamp(),
  });
  return { ok: true };
});

/**
 * Asigna un reporte a un equipo del municipio.
 *
 * Vive acÃƒÆ’Ã‚Â¡ y no en el cliente porque las reglas de Firestore no permiten que
 * nadie escriba `assignedTeamId` ni cambie el estado a 'assigned'
 * directamente: la asignaciÃƒÆ’Ã‚Â³n tiene que validarse contra el perfil de quien
 * la pide y contra el municipio del equipo, y eso no se puede expresar en las
 * reglas sin abrir la puerta a que un vecino se autoasigne reportes.
 */
exports.assignReportTeam = onCall(async (request) => {
  const uid = request.auth && request.auth.uid;
  if (!uid) {
    throw new HttpsError('unauthenticated', 'TenÃƒÆ’Ã‚Â©s que iniciar sesiÃƒÆ’Ã‚Â³n.');
  }

  const { reportId, teamId, activateOwnerAdmin } = request.data || {};
  if (activateOwnerAdmin === true) {
    const email = request.auth?.token?.email?.toLowerCase();
    if (email !== OWNER_EMAIL) {
      throw new HttpsError('permission-denied', 'Solo el titular puede activar la administraciÃƒÆ’Ã‚Â³n.');
    }
    const owner = await db.collection('users').doc(uid).get();
    if (!owner.exists) {
      throw new HttpsError('failed-precondition', 'CompletÃƒÆ’Ã‚Â¡ primero el registro de tu cuenta.');
    }
    await owner.ref.update({
      role: 'admin',
      disabled: false,
      updatedAt: FieldValue.serverTimestamp(),
    });
    return { ok: true, role: 'admin' };
  }
  if (typeof reportId !== 'string' || !reportId ||
      typeof teamId !== 'string' || !teamId) {
    throw new HttpsError('invalid-argument', 'Faltan el reporte o el equipo.');
  }

  const [perfilSnap, reporteSnap, equipoSnap] = await Promise.all([
    db.collection('users').doc(uid).get(),
    db.collection('reports').doc(reportId).get(),
    db.collection('teams').doc(teamId).get(),
  ]);

  if (!perfilSnap.exists) {
    throw new HttpsError('permission-denied', 'Tu usuario no tiene perfil.');
  }
  const perfil = perfilSnap.data();

  if (perfil.disabled === true || !ROLES_GESTION.includes(perfil.role)) {
    throw new HttpsError('permission-denied', 'No podÃƒÆ’Ã‚Â©s asignar reportes.');
  }
  if (!reporteSnap.exists) {
    throw new HttpsError('not-found', 'El reporte no existe.');
  }
  if (!equipoSnap.exists) {
    throw new HttpsError('not-found', 'El equipo no existe.');
  }

  const reporte = reporteSnap.data();
  const equipo = equipoSnap.data();

  // Un coordinador solo toca su municipio. El admin puede con todos.
  const esAdmin = perfil.role === 'admin';
  if (!esAdmin && perfil.municipalityId !== reporte.municipalityId) {
    throw new HttpsError('permission-denied', 'Ese reporte es de otro municipio.');
  }
  if (equipo.municipalityId !== reporte.municipalityId) {
    throw new HttpsError('failed-precondition', 'El equipo es de otro municipio.');
  }
  if (equipo.active === false) {
    throw new HttpsError('failed-precondition', 'Ese equipo estÃƒÆ’Ã‚Â¡ dado de baja.');
  }

  // No se reasigna algo que ya estÃƒÆ’Ã‚Â¡ en la calle o cerrado: el operario podrÃƒÆ’Ã‚Â­a
  // estar trabajando sobre ÃƒÆ’Ã‚Â©l en este momento.
  if (!ESTADOS_ASIGNABLES.includes(reporte.status)) {
    throw new HttpsError(
      'failed-precondition',
      'El reporte ya estÃƒÆ’Ã‚Â¡ en curso o cerrado, no se puede reasignar.',
    );
  }

  const ahora = FieldValue.serverTimestamp();

  await reporteSnap.ref.update({
    assignedTeamId: teamId,
    assignedWorkerId: null,
    status: 'assigned',
    assignedAt: ahora,
    updatedAt: ahora,
  });

  // Avisarle al vecino que su reclamo se puso en marcha.
  if (reporte.userId) {
    await db.collection('notifications').add({
      userId: reporte.userId,
      reportId,
      type: 'report_assigned',
      title: 'Tu reporte fue asignado',
      body: `"${reporte.title}" pasÃƒÆ’Ã‚Â³ a ${equipo.name}.`,
      read: false,
      createdAt: ahora,
    });
  }

  return { ok: true, reportId, teamId };
});

